CREATE TABLE IF NOT EXISTS users (email VARCHAR(254) PRIMARY KEY, password VARCHAR(100) NOT NULL, profile TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workouts (id VARCHAR(36) PRIMARY KEY, email VARCHAR(254) NOT NULL, data TEXT NOT NULL, FOREIGN KEY (email) REFERENCES users(email));
CREATE TABLE IF NOT EXISTS plans (id VARCHAR(36) PRIMARY KEY, email VARCHAR(254) NOT NULL, data TEXT NOT NULL, FOREIGN KEY (email) REFERENCES users(email));
CREATE TABLE IF NOT EXISTS wellness (email VARCHAR(254) NOT NULL, record_date VARCHAR(10) NOT NULL, data TEXT NOT NULL, PRIMARY KEY(email,record_date), FOREIGN KEY (email) REFERENCES users(email));

CREATE TABLE IF NOT EXISTS account_documents (email VARCHAR(254) PRIMARY KEY, document TEXT NOT NULL, version BIGINT NOT NULL DEFAULT 0);
